import React from 'react';
import {
    Alert,
    Autocomplete,
    Button,
    FormControl,
    FormHelperText,
    InputLabel,
    MenuItem,
    Select,
    Stack,
    Step,
    StepLabel,
    Stepper,
    TextField,
    Typography,
} from '@mui/material';
import ArrowBackIcon from '@mui/icons-material/ArrowBack';
import { AuthServices, AuthServicesError, ProfileServices, ProfileServicesError } from '@/api';
import { AppDialog } from '@/components/ui/AppDialog';
import { OtpInputBoxes, OTP_LENGTH } from '@/components/OtpInputBoxes';
import { LocationAutocomplete } from '@/components/ui/LocationAutocomplete';
import { Schools } from '@/constants/StaticData';
import { Gender, ProfileType, SchoolData, Validator } from '@/types/api.types';
import { AuthTokenResult } from '@/types/auth.types';
import { UpdateProfilePayload } from '@/types/profile.types';
import { IsProfileComplete, IsTokenValid, SetAccessTokenData, SetProfileComplete } from '@/utils/token';
import { useBodyScrollLock } from '@/hooks/useBodyScrollLock';

const OTP_RESEND_COOLDOWN_SECONDS = 30;
const MIN_ENTRY_YEAR = 1985;
// The API's [SchoolYear] validator rejects anything past the current year, so a derived
// exit year must stay within that range too.
const MAX_SCHOOL_YEAR = new Date().getFullYear();

/** identify → verify → profile. Each step is skipped when it is already satisfied. */
type Step = 'identify' | 'verify' | 'profile';

interface EventRegistrationAuthDialogProps {
    open: boolean;
    eventTitle?: string;
    onClose: () => void;
    /** Fired once the visitor holds a valid token AND a complete profile. */
    onReady: () => void;
    /**
     * Fired whenever stored auth state changes (token issued, profile completed) so the
     * caller can publish it to the rest of the app once the flow is over.
     */
    onAuthStateChanged?: () => void;
}

type CallOutcome<T> = { ok: true; data: T } | { ok: false; status: number };

const runCall = async <T,>(request: Promise<{ data: { status: number; result?: T } }>): Promise<CallOutcome<T>> => {
    try {
        const response = await request;
        const status = response?.data?.status ?? 0;
        if (status >= 200 && status < 300) {
            return { ok: true, data: response.data.result as T };
        }
        return { ok: false, status };
    } catch (error) {
        const status = (error as { response?: { status?: number } })?.response?.status ?? 0;
        return { ok: false, status };
    }
};

/** The step a visitor needs to start at, or null when nothing is pending. */
const pendingStep = (): Step | null => {
    if (!IsTokenValid()) return 'identify';
    if (!IsProfileComplete()) return 'profile';
    return null;
};

const entryYearOptions = (() => {
    const years: number[] = [];
    for (let year = MAX_SCHOOL_YEAR; year >= MIN_ENTRY_YEAR; year -= 1) years.push(year);
    return years;
})();

const entryClassOptions = [6, 7, 8, 9, 10, 11, 12];

/** Alumni never enter an exit year — it follows from the years spent between the two classes. */
const deriveExitYear = (entryYear: number, entryClass: number, exitClass: number): number => {
    if (entryYear <= 0 || entryClass <= 0 || exitClass <= 0) return 0;
    return entryYear + (exitClass - entryClass);
};

interface MinimalProfileForm {
    name: string;
    gender: string;
    phone: string;
    location: string;
    latitude: number;
    longitude: number;
    profileType: ProfileType;
    firstJnvId: number;
    entryYear: number;
    entryClass: number;
    exitClass: number;
    exitYear: number;
}

const emptyProfileForm: MinimalProfileForm = {
    name: '',
    gender: '',
    phone: '',
    location: '',
    latitude: 0,
    longitude: 0,
    profileType: ProfileType.Alumni,
    firstJnvId: 0,
    entryYear: 0,
    entryClass: 0,
    exitClass: 0,
    exitYear: 0,
};

/**
 * Signs a visitor in (and creates their profile when new) without leaving the event page.
 * Used by the public event link so "Register" never bounces the user through /login.
 */
export const EventRegistrationAuthDialog: React.FC<EventRegistrationAuthDialogProps> = ({
    open,
    eventTitle,
    onClose,
    onReady,
    onAuthStateChanged,
}) => {
    const [step, setStep] = React.useState<Step>('identify');
    const [email, setEmail] = React.useState<string>('');
    const [otp, setOtp] = React.useState<string>('');
    const [busy, setBusy] = React.useState<boolean>(false);
    const [error, setError] = React.useState<string>('');
    const [notice, setNotice] = React.useState<string>('');
    const [cooldown, setCooldown] = React.useState<number>(0);
    const [form, setForm] = React.useState<MinimalProfileForm>(emptyProfileForm);
    const [formTouched, setFormTouched] = React.useState<boolean>(false);

    useBodyScrollLock(open);

    // Re-evaluate where to start every time the dialog opens.
    React.useEffect(() => {
        if (!open) return;
        setError('');
        setNotice('');
        setOtp('');
        setFormTouched(false);
        // Clear any leftover resend cooldown, otherwise reopening the dialog within 30s
        // lands on the email step with a "Send code" button that silently does nothing.
        setCooldown(0);
        const next = pendingStep();
        if (next === null) {
            onReady();
            return;
        }
        setStep(next);
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [open]);

    React.useEffect(() => {
        if (cooldown <= 0) return;
        const timer = window.setInterval(() => setCooldown((prev) => (prev <= 1 ? 0 : prev - 1)), 1000);
        return () => window.clearInterval(timer);
    }, [cooldown]);

    const emailValid = Validator.IsEmail(email);
    const otpValid = otp.length === OTP_LENGTH && Validator.IsNumber(otp);
    const needsEntryClass = form.profileType === ProfileType.Alumni || form.profileType === ProfileType.Student;
    // Alumni left school, so they have an exit class; ex-staff have no class at all and
    // give their exit year directly. Current students/staff have neither.
    const needsExitClass = form.profileType === ProfileType.Alumni;
    const needsExitYear = form.profileType === ProfileType.ExStaff;

    const derivedExitYear = deriveExitYear(form.entryYear, form.entryClass, form.exitClass);
    // Classes that a person could actually have left in without the derived exit year
    // running past the current year.
    const exitClassOptions = entryClassOptions.filter((exitClass) => exitClass > form.entryClass
        && deriveExitYear(form.entryYear, form.entryClass, exitClass) <= MAX_SCHOOL_YEAR);
    const exitClassValid = form.exitClass > form.entryClass
        && derivedExitYear > 0
        && derivedExitYear <= MAX_SCHOOL_YEAR;
    const exitYearOptions = entryYearOptions.filter((year) => year > form.entryYear);
    const exitYearValid = form.exitYear >= MIN_ENTRY_YEAR && form.exitYear > form.entryYear;

    const profileValid =
        Validator.IsText(form.name)
        && Validator.IsText(form.gender)
        && Validator.IsPhone(form.phone)
        && Validator.IsText(form.location)
        && form.firstJnvId > 0
        && form.entryYear >= MIN_ENTRY_YEAR
        && (!needsEntryClass || form.entryClass > 0)
        && (!needsExitClass || exitClassValid)
        && (!needsExitYear || exitYearValid);

    const handleSendOtp = async () => {
        if (!emailValid || busy || cooldown > 0) return;
        setBusy(true);
        setError('');
        const outcome = await runCall(AuthServices.CreateOtp({ emailOrPhone: email }));
        setBusy(false);
        if (!outcome.ok) {
            setError(AuthServicesError.CreateOtpError(outcome.status));
            return;
        }
        setCooldown(OTP_RESEND_COOLDOWN_SECONDS);
        setNotice(`We sent a 6-digit code to ${email}.`);
        setStep('verify');
    };

    const handleVerify = async () => {
        if (!otpValid || busy) return;
        setBusy(true);
        setError('');
        const outcome = await runCall<AuthTokenResult>(AuthServices.CreateToken({ emailOrPhone: email, otp }));
        setBusy(false);
        if (!outcome.ok) {
            setError(AuthServicesError.CreateTokenError(outcome.status));
            return;
        }

        // Only localStorage is touched here. Broadcasting the new auth state (which
        // restructures the layout and invalidates the router) is deferred until the whole
        // flow finishes, otherwise this dialog would be unmounted mid-registration.
        SetAccessTokenData(outcome.data);
        onAuthStateChanged?.();

        if (outcome.data.xv) {
            onReady();
            return;
        }

        setNotice('');
        setForm((prev) => ({ ...prev, name: outcome.data.name || prev.name }));
        setStep('profile');
    };

    const handleSaveProfile = async () => {
        setFormTouched(true);
        if (!profileValid || busy) return;
        setBusy(true);
        setError('');

        const payload: UpdateProfilePayload = {
            name: form.name.trim(),
            gender: form.gender,
            phone: form.phone.trim(),
            location: form.location.trim(),
            profileType: form.profileType,
            firstJnvId: form.firstJnvId,
            entryYear: form.entryYear,
            entryClass: needsEntryClass ? form.entryClass : 0,
            exitClass: needsExitClass ? form.exitClass : 0,
            exitYear: needsExitClass
                ? derivedExitYear
                : needsExitYear ? form.exitYear : 0,
            ...(form.latitude !== 0 && form.longitude !== 0
                ? { latitude: form.latitude, longitude: form.longitude }
                : {}),
        };

        const outcome = await runCall(ProfileServices.UpdateProfile(payload));
        setBusy(false);
        if (!outcome.ok) {
            setError(ProfileServicesError.UpdateProfileError(outcome.status));
            return;
        }

        SetProfileComplete();
        onAuthStateChanged?.();
        onReady();
    };

    const activeStepIndex = step === 'profile' ? 1 : 0;
    const selectedSchool = Schools.find((school) => school.UniqueId === form.firstJnvId) ?? null;

    return (
        <AppDialog
            open={open}
            onClose={onClose}
            maxWidth="xs"
            busy={busy}
            dividers
            // Most visitors arrive from a shared link on a phone; a full-screen sheet
            // gives the profile step room instead of a 256px-wide dialog.
            fullScreenOnMobile
            title={`Register${eventTitle ? ` for ${eventTitle}` : ''}`}
            titleContent={
                <Stepper activeStep={activeStepIndex} alternativeLabel sx={{ mt: 2 }}>
                    <Step key="verify"><StepLabel>Verify</StepLabel></Step>
                    <Step key="profile"><StepLabel>Profile</StepLabel></Step>
                    <Step key="register"><StepLabel>Register</StepLabel></Step>
                </Stepper>
            }
            actions={
                <>
                    <Button onClick={onClose} disabled={busy} color="inherit">Cancel</Button>
                    {step === 'identify' && (
                        <Button
                            variant="contained"
                            onClick={handleSendOtp}
                            disabled={!emailValid || busy || cooldown > 0}
                        >
                            {busy ? 'Sending…' : cooldown > 0 ? `Resend in ${cooldown}s` : 'Send code'}
                        </Button>
                    )}
                    {step === 'verify' && (
                        <Button variant="contained" onClick={handleVerify} disabled={!otpValid || busy}>
                            {busy ? 'Verifying…' : 'Verify'}
                        </Button>
                    )}
                    {step === 'profile' && (
                        <Button variant="contained" onClick={handleSaveProfile} disabled={busy}>
                            {busy ? 'Saving…' : 'Continue'}
                        </Button>
                    )}
                </>
            }
        >
            {error && <Alert severity="error" sx={{ mb: 2 }}>{error}</Alert>}
            {!error && notice && <Alert severity="success" sx={{ mb: 2 }}>{notice}</Alert>}

                {step === 'identify' && (
                    <Stack spacing={2}>
                        <Typography variant="body2" color="text.secondary">
                            Enter your email to continue. We&apos;ll email you a 6-digit code — no password needed.
                            If you&apos;re new here, your account is created automatically.
                        </Typography>
                        <TextField
                            label="Email"
                            type="email"
                            autoComplete="email"
                            autoFocus
                            fullWidth
                            value={email}
                            error={!!email && !emailValid}
                            helperText={!!email && !emailValid ? 'Enter a valid email address.' : ' '}
                            onChange={(e) => setEmail(e.target.value.trim())}
                            onKeyDown={(e) => { if (e.key === 'Enter') handleSendOtp(); }}
                            disabled={busy}
                        />
                    </Stack>
                )}

                {step === 'verify' && (
                    <Stack spacing={2}>
                        <Typography variant="body2" color="text.secondary">
                            Enter the 6-digit code sent to <strong>{email}</strong>. You can also use a code from your
                            authenticator app.
                        </Typography>
                        <OtpInputBoxes value={otp} onChange={setOtp} autoFocus disabled={busy} />
                        <Stack direction="row" spacing={1} sx={{ justifyContent: 'space-between' }}>
                            <Button
                                size="small"
                                startIcon={<ArrowBackIcon />}
                                onClick={() => {
                                    // Going back to correct a mistyped address: clear the cooldown so
                                    // the code can be sent to the new address straight away.
                                    setStep('identify');
                                    setOtp('');
                                    setError('');
                                    setNotice('');
                                    setCooldown(0);
                                }}
                                disabled={busy}
                            >
                                Change email
                            </Button>
                            <Button
                                size="small"
                                onClick={handleSendOtp}
                                disabled={busy || cooldown > 0}
                            >
                                {cooldown > 0 ? `Resend in ${cooldown}s` : 'Resend code'}
                            </Button>
                        </Stack>
                    </Stack>
                )}

                {step === 'profile' && (
                    <Stack spacing={2}>
                        <Typography variant="body2" color="text.secondary">
                            Just a few details so the organisers know who&apos;s attending. You can add the rest to your
                            profile later.
                        </Typography>
                        <TextField
                            label="Full name"
                            required
                            fullWidth
                            autoComplete="name"
                            value={form.name}
                            error={formTouched && !Validator.IsText(form.name)}
                            onChange={(e) => setForm({ ...form, name: e.target.value })}
                            disabled={busy}
                        />
                        <FormControl fullWidth required error={formTouched && !Validator.IsText(form.gender)}>
                            <InputLabel id="reg-gender">Gender</InputLabel>
                            <Select
                                labelId="reg-gender"
                                label="Gender"
                                value={form.gender}
                                onChange={(e) => setForm({ ...form, gender: e.target.value })}
                                disabled={busy}
                            >
                                {Object.values(Gender).map((option) => (
                                    <MenuItem key={option} value={option}>{option}</MenuItem>
                                ))}
                            </Select>
                        </FormControl>
                        <FormControl fullWidth required>
                            <InputLabel id="reg-profile-type">I am a</InputLabel>
                            <Select
                                labelId="reg-profile-type"
                                label="I am a"
                                value={form.profileType}
                                onChange={(e) => setForm({
                                    ...form,
                                    profileType: e.target.value as ProfileType,
                                    entryClass: 0,
                                    exitClass: 0,
                                    exitYear: 0,
                                })}
                                disabled={busy}
                            >
                                <MenuItem value={ProfileType.Alumni}>JNV Alumni</MenuItem>
                                <MenuItem value={ProfileType.Student}>Current JNV Student</MenuItem>
                                <MenuItem value={ProfileType.ExStaff}>Former JNV Staff</MenuItem>
                                <MenuItem value={ProfileType.Staff}>Current JNV Staff</MenuItem>
                            </Select>
                        </FormControl>
                        <Autocomplete
                            options={Schools}
                            value={selectedSchool}
                            getOptionLabel={(option: SchoolData) => `[${option.StatePrefix}] JNV ${option.SchoolName}`}
                            isOptionEqualToValue={(option, value) => option.UniqueId === value.UniqueId}
                            onChange={(_e, value) => setForm({ ...form, firstJnvId: value ? value.UniqueId : 0 })}
                            disabled={busy}
                            renderInput={(params) => (
                                <TextField
                                    {...params}
                                    label="Entry JNV"
                                    required
                                    error={formTouched && form.firstJnvId === 0}
                                />
                            )}
                        />
                        <Stack direction="row" spacing={2}>
                            <FormControl fullWidth required error={formTouched && form.entryYear < MIN_ENTRY_YEAR}>
                                <InputLabel id="reg-entry-year">Entry year</InputLabel>
                                <Select
                                    labelId="reg-entry-year"
                                    label="Entry year"
                                    value={form.entryYear === 0 ? '' : form.entryYear}
                                    onChange={(e) => {
                                        const entryYear = Number(e.target.value);
                                        setForm({
                                            ...form,
                                            entryYear,
                                            // Drop previously picked exit values that no longer make
                                            // sense against the new entry year.
                                            exitYear: form.exitYear > entryYear ? form.exitYear : 0,
                                            exitClass: deriveExitYear(entryYear, form.entryClass, form.exitClass) <= MAX_SCHOOL_YEAR
                                                ? form.exitClass
                                                : 0,
                                        });
                                    }}
                                    disabled={busy}
                                >
                                    {entryYearOptions.map((year) => (
                                        <MenuItem key={year} value={year}>{year}</MenuItem>
                                    ))}
                                </Select>
                            </FormControl>
                            {needsExitYear && (
                                <FormControl fullWidth required error={formTouched && !exitYearValid}>
                                    <InputLabel id="reg-exit-year">Exit year</InputLabel>
                                    <Select
                                        labelId="reg-exit-year"
                                        label="Exit year"
                                        value={form.exitYear === 0 ? '' : form.exitYear}
                                        onChange={(e) => setForm({ ...form, exitYear: Number(e.target.value) })}
                                        disabled={busy || exitYearOptions.length === 0}
                                    >
                                        {exitYearOptions.map((year) => (
                                            <MenuItem key={year} value={year}>{year}</MenuItem>
                                        ))}
                                    </Select>
                                    {form.entryYear >= MIN_ENTRY_YEAR && exitYearOptions.length === 0 && (
                                        <FormHelperText>
                                            No exit year after that entry year — pick &quot;Current JNV Staff&quot;.
                                        </FormHelperText>
                                    )}
                                </FormControl>
                            )}
                        </Stack>
                        {needsEntryClass && (
                            <Stack direction="row" spacing={2}>
                                <FormControl fullWidth required error={formTouched && form.entryClass === 0}>
                                    <InputLabel id="reg-entry-class">Entry class</InputLabel>
                                    <Select
                                        labelId="reg-entry-class"
                                        label="Entry class"
                                        value={form.entryClass === 0 ? '' : form.entryClass}
                                        onChange={(e) => {
                                            const entryClass = Number(e.target.value);
                                            const keepsExitClass = form.exitClass > entryClass
                                                && deriveExitYear(form.entryYear, entryClass, form.exitClass) <= MAX_SCHOOL_YEAR;
                                            setForm({
                                                ...form,
                                                entryClass,
                                                exitClass: keepsExitClass ? form.exitClass : 0,
                                            });
                                        }}
                                        disabled={busy}
                                    >
                                        {entryClassOptions.map((entryClass) => (
                                            <MenuItem key={entryClass} value={entryClass}>{entryClass}</MenuItem>
                                        ))}
                                    </Select>
                                </FormControl>
                                {needsExitClass && (
                                    <FormControl fullWidth required error={formTouched && !exitClassValid}>
                                        <InputLabel id="reg-exit-class">Exit class</InputLabel>
                                        <Select
                                            labelId="reg-exit-class"
                                            label="Exit class"
                                            value={form.exitClass === 0 ? '' : form.exitClass}
                                            onChange={(e) => setForm({ ...form, exitClass: Number(e.target.value) })}
                                            disabled={busy || exitClassOptions.length === 0}
                                        >
                                            {exitClassOptions.map((exitClass) => (
                                                <MenuItem key={exitClass} value={exitClass}>{exitClass}</MenuItem>
                                            ))}
                                        </Select>
                                        {form.entryClass > 0 && exitClassOptions.length === 0 && (
                                            <FormHelperText>
                                                No exit class fits that entry year — pick &quot;Current JNV Student&quot;.
                                            </FormHelperText>
                                        )}
                                    </FormControl>
                                )}
                            </Stack>
                        )}
                        <TextField
                            label="Phone"
                            required
                            fullWidth
                            type="tel"
                            autoComplete="tel"
                            value={form.phone}
                            error={formTouched && !Validator.IsPhone(form.phone)}
                            helperText={formTouched && !Validator.IsPhone(form.phone) ? 'Enter a valid phone number.' : ' '}
                            onChange={(e) => setForm({ ...form, phone: e.target.value })}
                            disabled={busy}
                        />
                        <LocationAutocomplete
                            value={form.location}
                            required
                            error={formTouched && !Validator.IsText(form.location)}
                            disabled={busy}
                            onChange={(location, coordinates) => setForm({
                                ...form,
                                location,
                                latitude: coordinates?.latitude ?? 0,
                                longitude: coordinates?.longitude ?? 0,
                            })}
                        />
                    </Stack>
                )}
        </AppDialog>
    );
};
